#!/usr/bin/env node
// Real validation of the edge's information-disclosure protection and native error handling (0.2.0-rc.8 candidate). A workspace is
// created and started by an EARLIER release (rc.7: the edge that answered "The plain HTTP request was sent to HTTPS port ... nginx"),
// its responses are recorded, then the SAME workspace is reconciled by the candidate (the supported upgrade path: infra:apply +
// docker:up, nothing regenerated by hand) and every scenario is checked again with real HTTP and HTTPS requests, real Chrome (OIDC
// sign-in through Keycloak, microfrontend composition, screenshots of the error pages), a WebSocket upgrade, the orchestrator's rate
// limit, stopped and frozen containers, and finally a rollback to the earlier release.
//
//   node scripts/reference/validate-edge-security.mjs --from-cli <pso.js of rc.7> [--cli <pso.js of the candidate>] [--port 8471]
//        [--evidence <dir>] [--keep]
import { spawnSync } from "node:child_process";
import { createHash, X509Certificate, randomBytes } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative, resolve } from "node:path";
import { connect } from "node:tls";

const a = process.argv.slice(2);
const flag = (n) => { const i = a.indexOf(`--${n}`); return i < 0 ? undefined : a[i + 1]; };
const repo = resolve(new URL("../..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
const cli = flag("cli") ?? join(repo, "packages", "cli", "bin", "pso.js");
const fromCli = flag("from-cli");
if (!fromCli) { console.error("--from-cli <pso.js of the earlier release> is required (the workspace is created by it)"); process.exit(2); }
const port = Number(flag("port") ?? 8471);
const evidence = flag("evidence");
const keep = a.includes("--keep");
const infra = await import(new URL("../../packages/infra/dist/index.js", import.meta.url).href);
const { netRequest, environmentCa, localResolution, plan, DISCLOSURE, edgeImage } = infra;
const { INFRA_HOOKS } = await import(new URL("../../packages/cli/dist/commands-infra.js", import.meta.url).href);
const { chromium } = await import(new URL("../../node_modules/playwright-core/index.mjs", import.meta.url).href);
const WebSocket = (await import(new URL("../../node_modules/ws/wrapper.mjs", import.meta.url).href)).default;
const axeSource = readFileSync(join(repo, "node_modules", "axe-core", "axe.min.js"), "utf8");

const results = [];
const t0 = Date.now();
const stamp = () => `[${((Date.now() - t0) / 1000).toFixed(0).padStart(5)} s]`;
const check = (name, ok, detail = "") => { results.push({ name, ok: !!ok, ...(detail ? { detail: String(detail).slice(0, 500) } : {}) }); console.log(`${stamp()} ${ok ? "PASS" : "FAIL"}  ${name}${ok || !detail ? "" : ` - ${String(detail).slice(0, 500)}`}`); return !!ok; };
const run = (cwd, cmd, args, o = {}) => {
  const s = Date.now();
  const r = spawnSync(cmd, args, { cwd, encoding: "utf8", shell: o.shell ?? false, timeout: o.timeout ?? 1_800_000, maxBuffer: 256 * 1024 * 1024, env: { ...process.env, MSYS_NO_PATHCONV: "1", FORCE_COLOR: "0", PSO_NO_BROWSER: "1" } });
  const out = `${r.stdout ?? ""}${r.stderr ?? ""}`;
  console.log(`${stamp()}   ${o.label ?? `${cmd} ${args.join(" ")}`.slice(0, 160)} -> exit ${r.status} (${((Date.now() - s) / 1000).toFixed(1)} s)`);
  if (r.status !== 0 && !o.quiet) console.log(out.split(/\r?\n/).slice(-15).map((l) => `      | ${l}`).join("\n"));
  return { code: r.status, out };
};
const psoWith = (bin, tag) => (cwd, args, o = {}) => run(cwd, process.execPath, [bin, ...args], { ...o, label: `${tag} ${args.join(" ")}` });
const pso = psoWith(cli, "pso(candidate)");
const old = psoWith(fromCli, "pso(rc.7)");
const docker = (args) => run(process.cwd(), "docker", args, { quiet: true, label: `docker ${args.join(" ")}`.slice(0, 140) });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const base = mkdtempSync(join(tmpdir(), "pso-edgesec-")); const ws = join(base, "shop");
const project = `psoedge-${randomBytes(3).toString("hex")}`;
const shots = evidence ? join(evidence, "screenshots") : join(base, "screenshots"); mkdirSync(shots, { recursive: true });
const record = { cli, fromCli, port, project, before: [], after: [], rollback: [] };
const walk = (d, acc = []) => { for (const n of readdirSync(d)) { if (n === "node_modules" || n === ".git") continue; const f = join(d, n); statSync(f).isDirectory() ? walk(f, acc) : acc.push(relative(ws, f).split("\\").join("/")); } return acc; };
let up = false, browser;
try {
  // ------------------------------------------------------------------------------------------- 1. a workspace of the earlier release
  console.log(`${stamp()} workspace ${ws}, compose project ${project}, edge port ${port}`);
  check("rc.7: create workspace", old(base, ["create", "workspace", "shop"]).code === 0);
  for (const c of [["service", "catalog"], ["orchestrator", "gateway"], ["fei", "shop"], ["fei", "admin"], ["mei", "catalog", "--host", "shop", "--register", "--public"], ["mei", "orders", "--host", "shop", "--register"], ["mei", "users", "--host", "admin", "--register"]]) check(`rc.7: create ${c.join(" ")}`, old(ws, ["create", ...c]).code === 0);
  // PSO Channels (the WebSocket endpoint behind the edge) consumes its events through Dispatch: installed first, on Redis
  check("rc.7: dispatch:install redis --service gateway", old(ws, ["dispatch:install", "redis", "--service", "gateway"]).code === 0);
  check("rc.7: channels:enable --service gateway", old(ws, ["channels:enable", "--service", "gateway"]).code === 0);
  // the orchestrator serves /channels only when it declares at least one channel
  check("rc.7: make:channel products products --service gateway", old(ws, ["make:channel", "products", "products", "--pattern", "products", "--service", "gateway"]).code === 0);
  check("rc.7: infra:init --identity keycloak --runtime docker --users ana", old(ws, ["infra:init", "--identity", "keycloak", "--runtime", "docker", "--users", "ana"]).code === 0);
  const contractFile = join(ws, "pso.infra.json");
  const contract = JSON.parse(readFileSync(contractFile, "utf8"));
  contract.environments.local.httpsPort = port; contract.docker = { project };
  // the orchestrator's own rate limit (an application setting): a small burst so the validation can reach it
  contract.services = { ...(contract.services ?? {}), gateway: { environment: { PSO_DISPATCH_ENABLED: "true", RATE_LIMIT_PER_MINUTE: "240", RATE_LIMIT_BURST: "25" } } };
  contract.redis = { clients: { gateway: ["REDIS_URL"] } };
  contract.environments.local.redis = { port: port + 10000 };
  writeFileSync(contractFile, JSON.stringify(contract, null, 2) + "\n");
  check("rc.7: infra:apply", old(ws, ["infra:apply", "--yes"]).code === 0);
  for (const d of ["frontends/fei-shop", "frontends/fei-admin", "frontends/modules/mei-catalog", "frontends/modules/mei-orders", "frontends/modules/mei-users"]) check(`npm install in ${d}`, run(join(ws, ...d.split("/")), "npm", ["install", "--no-audit", "--no-fund"], { shell: true, timeout: 900_000 }).code === 0);
  check("rc.7: frontend:build --env local", old(ws, ["frontend:build", "--env", "local"]).code === 0);
  check("rc.7: frontend:publish --all --env local", old(ws, ["frontend:publish", "--all", "--env", "local"]).code === 0);
  const u0 = old(ws, ["docker:up", "--vendor", "--timeout", "1200"]); up = true;
  check("rc.7: docker:up --vendor (every container healthy)", u0.code === 0, u0.out.slice(-400));

  const p = plan(ws, "local", INFRA_HOOKS); const t = p.topology, ca = environmentCa(ws, t), map = localResolution(t);
  const shop = t.frontends.find((f) => f.name === "fei-shop"), adm = t.frontends.find((f) => f.name === "fei-admin");
  const url = (host, path, scheme = "https") => `${scheme}://${host}:${port}${path}`;
  const req = async (u, o = {}) => { try { return await netRequest({ url: u, ca, resolve: map, timeoutMs: 30_000, ...o }); } catch (e) { return { status: 0, headers: {}, body: Buffer.from(String(e.message)), timeMs: 0 }; } };
  const raw = (servername, payload, untilHeaders = false) => new Promise((res) => {
    let b = ""; const s = connect({ host: "127.0.0.1", port, servername, ca, rejectUnauthorized: false }, () => s.write(payload));
    const done = () => { s.destroy(); res(b); }; s.on("data", (d) => { b += d.toString("latin1"); if (untilHeaders && b.includes("\r\n\r\n")) done(); }); s.on("end", done); s.on("error", done); setTimeout(done, 15_000);
  });
  const KEEP = ["server", "x-powered-by", "content-type", "www-authenticate", "retry-after", "allow", "x-correlation-id", "strict-transport-security", "content-security-policy", "cache-control"];
  const ofRaw = (s) => { const [head, ...rest] = s.split("\r\n\r\n"); const lines = head.split("\r\n"); const headers = {}; for (const l of lines.slice(1)) { const i = l.indexOf(":"); if (i > 0) headers[l.slice(0, i).toLowerCase()] = l.slice(i + 1).trim(); } return { status: Number(lines[0].split(" ")[1] ?? 0), headers, body: Buffer.from(rest.join("\r\n\r\n"), "latin1") }; };
  const scenarios = [
    ["plain HTTP to the HTTPS port (shop)", () => req(url(shop.host, "/", "http"))],
    ["plain HTTP to the HTTPS port (API)", () => req(url(t.api.host, "/products", "http"))],
    ["shell (200)", () => req(url(shop.host, "/"))],
    ["SPA route", () => req(url(shop.host, "/catalog"))],
    ["API without a token (401)", () => req(url(t.api.host, "/products"))],
    ["same-origin API without a token (401)", () => req(url(shop.host, "/api/products"))],
    ["missing asset of shop", () => req(url(shop.host, "/fei/assets/does-not-exist.js"))],
    ["missing asset of admin", () => req(url(adm.host, "/fei/assets/does-not-exist.js"))],
    ["unknown host", async () => ofRaw(await raw(`nowhere.${t.domain}`, `GET / HTTP/1.1\r\nHost: nowhere.${t.domain}\r\nConnection: close\r\n\r\n`))],
    ["malformed request line", async () => ofRaw(await raw(shop.host, "GARBAGE \u0001\r\n\r\n"))],
    ["request body too large (API)", async () => ofRaw(await raw(t.api.host, `POST /products HTTP/1.1\r\nHost: ${t.api.host}\r\nContent-Type: application/json\r\nContent-Length: 30000000\r\nConnection: close\r\n\r\n`))],
    ["internal error location requested directly", () => req(url(shop.host, "/__edge_error__/html/404.html"))],
  ];
  const snapshot = async (into) => {
    const out = {};
    for (const [name, fn] of scenarios) {
      const r = await fn();
      const headers = Object.fromEntries(KEEP.filter((k) => r.headers[k] !== undefined).map((k) => [k, String(r.headers[k])]));
      out[name] = { status: r.status, headers, body: r.body.toString("utf8").slice(0, 6000) };
      into.push({ name, ...out[name] });
    }
    return out;
  };
  const before = await snapshot(record.before);
  check("before (rc.7): plain HTTP on the HTTPS port discloses nginx (the reported defect, reproduced)", before["plain HTTP to the HTTPS port (shop)"].status === 400 && /nginx/.test(before["plain HTTP to the HTTPS port (shop)"].body) && /plain HTTP request was sent to HTTPS port/.test(before["plain HTTP to the HTTPS port (shop)"].body), JSON.stringify(before["plain HTTP to the HTTPS port (shop)"]).slice(0, 300));
  check("before (rc.7): every response names the server (Server: nginx)", before["shell (200)"].headers.server === "nginx" && before["API without a token (401)"].headers.server === "nginx");
  const filesBefore = new Set(walk(ws));

  // ------------------------------------------------------------------------------------------- 2. the candidate reconciles the same workspace
  const pl = pso(ws, ["infra:plan", "--env", "local"]);
  check("candidate: infra:plan names exactly the edge configuration and the compose file as updates", pl.code === 0 && /nginx:edge/.test(pl.out) && /docker:compose/.test(pl.out), pl.out.split("\n").filter((l) => /update|create|replace/.test(l)).join(" | "));
  check("candidate: infra:apply", pso(ws, ["infra:apply", "--env", "local", "--yes"]).code === 0);
  const u1 = pso(ws, ["docker:up", "--env", "local", "--timeout", "900"]);
  check("candidate: docker:up (edge image ensured, nginx -t passed, edge re-created; nothing else to do by hand)", u1.code === 0 && /edge configuration accepted by nginx -t/.test(u1.out), u1.out.split("\n").filter((l) => /edge|error|nginx/i.test(l)).slice(0, 10).join(" | "));
  const edgeId = docker(["ps", "-q", "--filter", `label=com.docker.compose.project=${project}`, "--filter", "label=com.docker.compose.service=edge"]).out.trim();
  const edgeImg = docker(["inspect", "--format", "{{.Config.Image}}", edgeId]).out.trim();
  check(`the running edge uses the framework image of the candidate (${edgeImage().tag})`, edgeImg === edgeImage().tag, edgeImg);
  const filesAfter = walk(ws);
  const added = filesAfter.filter((f) => !filesBefore.has(f));
  check("17. the upgrade added no file outside PSO's journal, backups and state (no error page anywhere in the workspace)", added.every((f) => /^\.infra\/(journal|backups|logs)\//.test(f) || f === ".infra/state.json"), added.join(", "));
  const holding = filesAfter.filter((f) => { try { return /__edge_error__|Error \d{3}<\/p>|"type":"about:blank"|page\.html/.test(readFileSync(join(ws, f), "utf8")); } catch { return false; } });
  check("17. no file of the workspace, its FEIs, MEIs or .infra/ holds error-page content or the internal error location", holding.length === 0, holding.join(", "));
  const feiFiles = filesAfter.filter((f) => /^frontends\//.test(f) && /\b(4\d\d|5\d\d)\.(html|json)$/.test(f));
  check("17. no status page in any FEI or MEI project", feiFiles.length === 0, feiFiles.join(", "));

  // ------------------------------------------------------------------------------------------- 3. the same requests after the upgrade
  const after = await snapshot(record.after);
  const anon = (r) => !r.headers.server && !r.headers["x-powered-by"];
  const clean = (r) => anon(r) && !DISCLOSURE.test(r.body.replace(/<style>[\s\S]*?<\/style>/g, ""));
  check("1. plain HTTP to the HTTPS port: 400, the edge's own page, nothing identifying", after["plain HTTP to the HTTPS port (shop)"].status === 400 && /Error 400/.test(after["plain HTTP to the HTTPS port (shop)"].body) && clean(after["plain HTTP to the HTTPS port (shop)"]), JSON.stringify(after["plain HTTP to the HTTPS port (shop)"]).slice(0, 300));
  check("1. ... on the API host: 400 application/problem+json", after["plain HTTP to the HTTPS port (API)"].status === 400 && after["plain HTTP to the HTTPS port (API)"].headers["content-type"] === "application/problem+json" && clean(after["plain HTTP to the HTTPS port (API)"]));
  check("2/4. malformed request line: 400 sanitized", after["malformed request line"].status === 400 && clean(after["malformed request line"]), JSON.stringify(after["malformed request line"]).slice(0, 200));
  check("4. unknown host: 421 sanitized", after["unknown host"].status === 421 && clean(after["unknown host"]), JSON.stringify(after["unknown host"]).slice(0, 200));
  check("3. no Server and no X-Powered-By on any response (success, application errors, edge errors)", Object.values(after).every(anon), Object.entries(after).filter(([, r]) => !anon(r)).map(([n, r]) => `${n}: ${r.headers.server ?? ""} ${r.headers["x-powered-by"] ?? ""}`).join("; "));
  check("6. request body too large: 413 problem document from the edge", after["request body too large (API)"].status === 413 && /application\/problem\+json/.test(after["request body too large (API)"].headers["content-type"] ?? "") && /"status":413/.test(after["request body too large (API)"].body));
  const p401 = after["API without a token (401)"], b401 = before["API without a token (401)"];
  check("5/9/10. the orchestrator's 401 Problem Details pass unchanged (status, Content-Type, WWW-Authenticate, X-Correlation-ID, code)", p401.status === 401 && p401.headers["content-type"] === b401.headers["content-type"] && p401.headers["www-authenticate"] === b401.headers["www-authenticate"] && !!p401.headers["x-correlation-id"] && JSON.parse(p401.body).code === JSON.parse(b401.body).code, `${JSON.stringify(p401.headers)} ${p401.body.slice(0, 200)}`);
  check("5. ... the same through the shell's same-origin API path", after["same-origin API without a token (401)"].status === 401 && JSON.parse(after["same-origin API without a token (401)"].body).code === JSON.parse(b401.body).code);
  check("11. a missing asset of each FEI: 404 with the edge's page (shop and admin share one protection)", ["missing asset of shop", "missing asset of admin"].every((n) => after[n].status === 404 && /Error 404/.test(after[n].body) && clean(after[n])), JSON.stringify(after["missing asset of admin"]).slice(0, 200));
  check("12. SPA routes and the shell are unchanged (200, same document as before)", after["shell (200)"].status === 200 && after["SPA route"].status === 200 && after["SPA route"].body === before["SPA route"].body);
  check("18. the internal error location is not reachable (404 page, never a file of the image)", after["internal error location requested directly"].status === 404 && /Error 404/.test(after["internal error location requested directly"].body));
  check("10. the edge keeps its security headers on error responses (HSTS, restrictive CSP, no-store)", /max-age/.test(after["missing asset of shop"].headers["strict-transport-security"] ?? "") && /default-src 'none'/.test(after["missing asset of shop"].headers["content-security-policy"] ?? "") && after["missing asset of shop"].headers["cache-control"] === "no-store");
  // MEI composition: the released microfrontend's federation manifest, through the edge
  const pointer = await req(url(shop.host, "/_mei/mei-catalog/active.json"));
  const meiVersion = pointer.status === 200 ? JSON.parse(pointer.body.toString()).version : undefined;
  const entry = meiVersion ? await req(url(shop.host, `/_mei/mei-catalog/v/${meiVersion}/remoteEntry.js`)) : { status: 0, headers: {}, body: Buffer.from("") };
  check("12. the microfrontend's release pointer and Module Federation entry are served through the edge (200)", pointer.status === 200 && /json/.test(String(pointer.headers["content-type"])) && entry.status === 200 && /javascript/.test(String(entry.headers["content-type"])) && anon(entry), `${pointer.status} ${meiVersion} ${entry.status}`);
  const staleEntry = await req(url(shop.host, "/_mei/mei-catalog/v/0.0.0-missing/remoteEntry.js"));
  check("12. a missing microfrontend release answers 404 (status kept; the shell reports the module as unavailable)", staleEntry.status === 404 && anon(staleEntry));
  const rcfg = await req(url(shop.host, "/pso-runtime-config.json"));
  check("12. the shell's runtime configuration and release pointer are served unchanged", rcfg.status === 200 && JSON.parse(rcfg.body.toString()).fei === "fei-shop");

  // OIDC token endpoint and API through the edge (Keycloak's direct client, development only)
  const apiSecret = readFileSync(join(ws, ".infra", "secrets", "local", "idp-api-client"), "utf8").trim();
  const userPwd = readFileSync(join(ws, ".infra", "secrets", "local", "user-ana"), "utf8").trim();
  const tok = await req(t.identity.tokenEndpoint.replace(/:\d+\//, `:${port}/`), { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ grant_type: "password", client_id: "pso-api-client", client_secret: apiSecret, username: "ana", password: userPwd, scope: "openid" }).toString() });
  const access = tok.status === 200 ? JSON.parse(tok.body.toString()).access_token : undefined;
  check("13. OIDC: a token from Keycloak's token endpoint through the edge", !!access, `${tok.status} ${tok.body.toString().slice(0, 160)}`);
  const authed = await req(url(t.api.host, "/products"), { headers: { authorization: `Bearer ${access}` } });
  check("13. JWT validation against Keycloak's keys: GET /products with the token -> 200", authed.status === 200 && anon(authed), `${authed.status} ${authed.body.toString().slice(0, 160)}`);
  // WebSocket (PSO Channels) through the edge
  const wsResult = await new Promise((res) => {
    const s = new WebSocket(`wss://127.0.0.1:${port}/channels`, "pso.channels.v1", { ca, servername: shop.host, headers: { host: `${shop.host}:${port}` } });
    // no Origin: a non-browser client, judged by its token. (A browser Origin on a port other than 443 is refused by the orchestrator in
    // development: the edge forwards Host without the port; pre-existing since rc.7, reported separately)
    const done = (v) => { try { s.close(); } catch { /* closed */ } res(v); };
    s.on("upgrade", (r) => { if (r.headers.server) done({ error: `server header ${r.headers.server}` }); });
    s.on("message", (m) => { const f = JSON.parse(m.toString()); if (f.t === "ready") s.send(JSON.stringify({ v: 1, t: "auth", token: access })); else if (f.t === "ack" && f.authenticated) done({ authenticated: true }); else if (f.t === "error") done({ error: f.code }); });
    s.on("error", (e) => done({ error: e.message })); setTimeout(() => done({ error: "timeout" }), 20_000);
  });
  check("13. WebSocket: PSO Channels upgrade through the edge (101), authenticated with the OIDC token", wsResult.authenticated === true, JSON.stringify(wsResult));
  // the orchestrator's rate limit
  const burst = await Promise.all(Array.from({ length: 60 }, () => req(url(t.api.host, "/products"), { headers: { authorization: `Bearer ${access}` } })));
  const limited = burst.find((r) => r.status === 429);
  check("6. rate limiting: the orchestrator's 429 reaches the client unchanged (problem document, Retry-After)", !!limited && /application\/problem\+json/.test(String(limited.headers["content-type"])) && !!limited.headers["retry-after"] && JSON.parse(limited.body.toString()).code === "PSO_RATE_LIMITED" && anon(limited), limited ? JSON.stringify(limited.headers) : burst.map((r) => r.status).join(","));
  await sleep(8000);
  const probe = pso(ws, ["infra:validate", "--env", "local", "--probe"]);
  check("infra:validate --probe: TLS everywhere, plus the new edge probes (plain HTTP and unknown host sanitized)", probe.code === 0 && /plain HTTP on the TLS port/.test(probe.out), probe.out.split("\n").filter((l) => /edge:|FAIL|✗|fail/i.test(l)).join(" | "));

  // ------------------------------------------------------------------------------------------- 4. real Chrome
  const leaf = new X509Certificate(readFileSync(join(ws, ".infra", "certs", "local", "edge", "tls.crt")));
  const spki = createHash("sha256").update(leaf.publicKey.export({ type: "spki", format: "der" })).digest("base64");
  browser = await chromium.launch({ channel: "chrome", args: [`--host-resolver-rules=MAP *.${t.domain} 127.0.0.1`, `--ignore-certificate-errors-spki-list=${spki}`] });
  const open = async (u, o = {}) => {
    const ctx = await browser.newContext({ viewport: o.viewport ?? { width: 1280, height: 800 }, colorScheme: o.dark ? "dark" : "light" });
    const page = await ctx.newPage(); const s = { page, ctx, errors: [], console: [] };
    page.on("pageerror", (e) => s.errors.push(e.message)); page.on("console", (m) => s.console.push(m.text()));
    s.response = await page.goto(u, { waitUntil: "networkidle", timeout: 60_000 }).catch((e) => ({ status: () => 0, error: e.message }));
    return s;
  };
  const shop1 = await open(shop.url); await shop1.page.waitForTimeout(1500);
  await shop1.page.goto(new URL("catalog", shop.url).href, { waitUntil: "networkidle", timeout: 60_000 }); await shop1.page.waitForTimeout(2000);
  const catText = await shop1.page.locator("body").innerText().catch(() => "");
  await shop1.page.screenshot({ path: join(shots, "app-shop-catalog-mei.png") });
  check("12. browser: the public shell composes the Catalog microfrontend (SPA navigation, Module Federation)", /catalog/i.test(catText) && !/module unavailable|not configured/i.test(catText) && shop1.errors.length === 0, `${catText.slice(0, 160)} ${shop1.errors.join(" | ")}`);
  const admin = await open(adm.url); await admin.page.waitForTimeout(1500);
  const offers = admin.page.locator("button, a").filter({ hasText: /sign in|log in|continue/i });
  if (!(/realms\//.test(admin.page.url())) && await offers.count()) { await offers.first().click(); }
  await admin.page.waitForSelector("#username", { timeout: 30_000 }).catch(() => undefined);
  if (await admin.page.locator("#username").count()) { await admin.page.fill("#username", "ana"); await admin.page.fill("#password", userPwd); await admin.page.click("#kc-login"); await admin.page.waitForURL((x) => x.origin === adm.origin, { timeout: 60_000 }).catch(() => undefined); await admin.page.waitForTimeout(2500); }
  await admin.page.screenshot({ path: join(shots, "app-admin-signed-in.png") });
  check("13. browser: OIDC sign-in (authorization code + PKCE) at Keycloak through the edge, back to the admin shell", new URL(admin.page.url()).origin === adm.origin && !(await admin.page.locator("#kc-login").count()) && admin.errors.length === 0, `${admin.page.url()} ${admin.errors.join(" | ")}`);
  const pageCheck = async (label, u, code, file, o = {}) => {
    const s = await open(u, o);
    const status = s.response.status();
    const h1 = await s.page.locator("h1").innerText().catch(() => "");
    const styled = await s.page.evaluate(() => getComputedStyle(document.body).display).catch(() => "");
    const blocked = s.console.filter((m) => /Content Security Policy|Refused/i.test(m));
    await s.page.screenshot({ path: join(shots, file) });
    let violations = [];
    if (o.axe) { await s.page.evaluate(axeSource); violations = (await s.page.evaluate(async () => (await window.axe.run(document, { runOnly: ["wcag2a", "wcag2aa", "wcag21aa", "best-practice"] })).violations.map((v) => `${v.id}:${v.nodes.length}`))); }
    await s.ctx.close();
    check(`browser: ${label} -> ${code}, styled under its CSP, nothing blocked${o.axe ? ", axe: no violation" : ""}`, status === code && !!h1 && styled === "flex" && blocked.length === 0 && violations.length === 0, `${status} "${h1}" display=${styled} ${blocked.join(" | ")} ${violations.join(",")}`);
  };
  await pageCheck("plain HTTP on the HTTPS port", url(shop.host, "/", "http"), 400, "edge-400-plain-http.png", { axe: true });
  await pageCheck("missing page of shop", url(shop.host, "/fei/assets/missing-page.js"), 404, "edge-404-desktop.png", { axe: true });
  await pageCheck("missing page, phone, dark scheme", url(adm.host, "/fei/assets/missing-page.js"), 404, "edge-404-phone-dark.png", { viewport: { width: 390, height: 780 }, dark: true });
  await pageCheck("unknown host", url(`nowhere.${t.domain}`, "/"), 421, "edge-421-unknown-host.png");

  // ------------------------------------------------------------------------------------------- 5. outages: frozen and stopped containers
  const cid = (svc) => docker(["ps", "-aq", "--filter", `label=com.docker.compose.project=${project}`, "--filter", `label=com.docker.compose.service=${svc}`]).out.trim().split(/\s+/)[0];
  docker(["pause", cid("gateway")]);
  const frozen = await req(url(t.api.host, "/products"));
  check("7. the orchestrator does not answer (frozen): 504 problem document after the connect timeout", frozen.status === 504 && frozen.headers["content-type"] === "application/problem+json" && anon(frozen), `${frozen.status} ${frozen.timeMs} ms ${frozen.body.toString().slice(0, 120)}`);
  record.after.push({ name: "frozen orchestrator", status: frozen.status, headers: Object.fromEntries(KEEP.filter((k) => frozen.headers[k]).map((k) => [k, String(frozen.headers[k])])), body: frozen.body.toString().slice(0, 300) });
  docker(["unpause", cid("gateway")]);
  for (const svc of ["gateway", "fei-shop", "fei-admin", "catalog", "idp"]) docker(["stop", cid(svc)]);
  await sleep(12_000);
  const down = { api: await req(url(t.api.host, "/products")), same: await req(url(shop.host, "/api/products")), shop: await req(url(shop.host, "/")), admin: await req(url(adm.host, "/orders")), idp: await req(url(t.identity.host, "/realms/shop/account")), token: await req(t.identity.tokenEndpoint.replace(/:\d+\//, `:${port}/`), { method: "POST", body: "grant_type=x" }) };
  for (const [k, r] of Object.entries(down)) record.after.push({ name: `stopped: ${k}`, status: r.status, headers: Object.fromEntries(KEEP.filter((x) => r.headers[x]).map((x) => [x, String(r.headers[x])])), body: r.body.toString().slice(0, 300) });
  check("7/8. orchestrator stopped: 502 problem documents on the API host and the same-origin path", [down.api, down.same].every((r) => r.status === 502 && r.headers["content-type"] === "application/problem+json" && anon(r)), `${down.api.status} ${down.same.status}`);
  check("8. every application container stopped: both shells answer the edge's 502 page", [down.shop, down.admin].every((r) => r.status === 502 && /Error 502/.test(r.body.toString()) && clean({ headers: r.headers, body: r.body.toString() })), `${down.shop.status} ${down.admin.status}`);
  check("8. identity provider stopped: a page for the browser, a problem document for the token endpoint", down.idp.status === 502 && /Error 502/.test(down.idp.body.toString()) && down.token.status === 502 && down.token.headers["content-type"] === "application/problem+json", `${down.idp.status} ${down.token.status}`);
  await pageCheck("every application container stopped", url(shop.host, "/"), 502, "edge-502-services-stopped.png", { axe: true });
  const logs = docker(["logs", "--tail", "200", cid("edge")]).out;
  check("diagnostics stay internal: the edge's log names the cause and the correlation id, without query strings", /could not be resolved|connect\(\) failed|upstream timed out/.test(logs) && /id=[0-9a-f]{32}/.test(logs) && !/code=|password=/.test(logs));
  // the pages of every status, from the running image itself (not from the repository)
  const gallery = [];
  for (const code of [400, 401, 403, 404, 405, 413, 429, 500, 502, 503, 504]) {
    const html = docker(["exec", cid("edge"), "cat", `/usr/share/edge/errors/html/${code}.html`]).out;
    const ctx = await browser.newContext({ viewport: { width: 900, height: 560 } }); const pg = await ctx.newPage(); await pg.setContent(html); await pg.screenshot({ path: join(shots, `page-${code}.png`) }); await ctx.close();
    gallery.push({ code, clean: !DISCLOSURE.test(html.replace(/<style>[\s\S]*?<\/style>/, "")) });
  }
  check("every status page read from the running edge image is free of technology names, versions, paths and traces", gallery.every((g) => g.clean), JSON.stringify(gallery));
  await browser.close(); browser = undefined;
  const again = pso(ws, ["docker:up", "--env", "local", "--timeout", "900"]);
  check("recovery: docker:up brings every stopped container back", again.code === 0 && (await req(url(shop.host, "/"))).status === 200);

  // ------------------------------------------------------------------------------------------- 6. rollback to the earlier release
  check("rollback: rc.7 infra:apply re-renders its own edge configuration", old(ws, ["infra:apply", "--env", "local", "--yes"]).code === 0);
  const rb = old(ws, ["docker:up", "--env", "local", "--timeout", "900"]);
  const rbImg = docker(["inspect", "--format", "{{.Config.Image}}", cid("edge")]).out.trim();
  const rbShell = await req(url(shop.host, "/"));
  check("rollback: the stack runs again on rc.7 (its stock edge image), the shell answers 200", rb.code === 0 && rbImg === "nginx:1.27-alpine" && rbShell.status === 200, `${rbImg} ${rbShell.status}`);
  record.rollback.push({ name: "plain HTTP after rollback", ...(await (async () => { const r = await req(url(shop.host, "/", "http")); return { status: r.status, server: r.headers.server, body: r.body.toString().slice(0, 300) }; })()) });
  const fwd = pso(ws, ["infra:apply", "--env", "local", "--yes"]).code === 0 && pso(ws, ["docker:up", "--env", "local", "--timeout", "900"]).code === 0;
  const fwdPlain = await req(url(shop.host, "/", "http"));
  check("forward again: the candidate restores the protection on the same workspace (no migration step)", fwd && fwdPlain.status === 400 && !fwdPlain.headers.server && /Error 400/.test(fwdPlain.body.toString()));
} finally {
  await browser?.close().catch(() => undefined);
  if (!keep) { pso(ws, ["docker:down", "--env", "local", "--volumes", "--yes"], { quiet: true }); }
  const failed = results.filter((r) => !r.ok).length;
  if (evidence) { mkdirSync(evidence, { recursive: true }); writeFileSync(join(evidence, "edge-security.json"), JSON.stringify({ ...record, results, durationSeconds: Math.round((Date.now() - t0) / 1000), at: new Date().toISOString() }, null, 2)); }
  if (!keep) { try { rmSync(base, { recursive: true, force: true, maxRetries: 5 }); } catch { /* temp */ } }
  console.log(`\n${results.length - failed}/${results.length} checks passed${failed ? `, ${failed} FAILED` : ""}`);
  process.exitCode = failed ? 1 : 0;
}
